from pathlib import Path
import json, hashlib, html, datetime
root = Path("qa/evidence/2026-09-18-draft-fixes")
captions = ["\u63d0\u9192\u65f6\u95f4\u8349\u7a3f\u5207\u9875\u4fdd\u7559","\u56de\u987e\u5217\u51fa\u9690\u85cf\u4efb\u52a1\u8349\u7a3f","\u8df3\u8f6c\u5e76\u805a\u7126\u4efb\u52a1\u8fdb\u5c55","\u5907\u4efd\u660e\u786e\u9009\u62e9\u672a\u63d0\u4ea4\u8f93\u5165\u8303\u56f4","\u4ec5\u5bfc\u51fa\u5df2\u63d0\u4ea4\u5185\u5bb9\uff0c\u63d0\u793a\u9057\u6f0f 2 \u5904","\u4fdd\u5b58\u5168\u90e8\u5e76\u5bfc\u51fa\u5b8c\u6210","\u771f\u5b9e\u6a21\u578b\u8f93\u51fa\u7684\u9605\u8bfb\u6392\u7248","\u4eba\u5de5\u7f16\u8f91\u540e\u91c7\u7eb3\uff0c\u957f\u56de\u987e\u6298\u53e0","\u5c55\u5f00\u5b8c\u6574\u56de\u987e","\u4ee3\u7801\u5757\u4e0e\u6536\u8d77\u64cd\u4f5c","\u5386\u53f2\u9875\u7684\u56de\u987e\u9605\u8bfb\u6001","\u65e0\u6548\u63d0\u9192\u65f6\u95f4\u4fdd\u7559\u5f85\u4fee\u6b63","\u9000\u51fa\u63d0\u4f9b\u67e5\u770b\u4e0e\u4fdd\u5b58\u9009\u9879","\u9000\u51fa\u8fd4\u56de\u5177\u4f53\u8349\u7a3f\u6e05\u5355","\u9519\u8bef\u540e\u5b9a\u4f4d\u8f93\u5165\uff0c\u4e0d\u91cd\u590d\u5f39\u7a97"]
items = []
assert len(list(root.glob("*.jpg"))) == len(captions)
for p, caption in zip(sorted(root.glob("*.jpg")), captions):
    items.append(dict(file=p.name, caption=caption, ax=p.with_suffix(".txt").name, bytes=p.stat().st_size, sha256=hashlib.sha256(p.read_bytes()).hexdigest()))
(root / "screenshots-manifest.json").write_text(json.dumps(dict(date="2026-09-18", mode="app.daylog.qa --demo", screenshots=items), ensure_ascii=False, indent=2))
cards = "".join(f'<article><a href="{i["file"]}"><img loading="lazy" src="{i["file"]}" alt="{html.escape(i["caption"])}"></a><h2>{n:02d} {html.escape(i["caption"])}</h2><a href="{i["ax"]}">Accessibility evidence</a></article>' for n, i in enumerate(items, 1))
title = "DayLog \u00b7 \u8349\u7a3f\u4e0e\u9605\u8bfb\u4fee\u590d\u9a8c\u6536"
intro = "2026-09-18 \u00b7 15 \u5f20\u539f\u751f\u622a\u56fe\uff0c\u70b9\u51fb\u67e5\u770b\u539f\u56fe\u3002\u4f7f\u7528\u9694\u79bb\u6f14\u793a\u6570\u636e\u3002\u7b2c 07 \u5f20\u4e3a\u771f\u5b9e\u6a21\u578b\u8f93\u51fa\uff0c\u7b2c 08\u201411 \u5f20\u4e3a\u4eba\u5de5\u7f16\u8f91\u540e\u7684\u683c\u5f0f\u9a8c\u6536\u3002\u672c\u753b\u5eca\u4fdd\u5b58\u5728\u672c\u673a\u3002"
page = f'<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><style>body{{margin:0;background:#f5f3f0;color:#282726;font:16px -apple-system,BlinkMacSystemFont,sans-serif}}main{{max-width:1320px;margin:auto;padding:32px 20px}}h1{{font-size:28px}}p{{line-height:1.7;color:#62605d}}a{{color:#965a36}}section{{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,440px),1fr));gap:20px}}article{{padding:16px;background:white;border:1px solid #e2ddd7;border-radius:14px}}img{{width:100%;height:330px;object-fit:contain;background:#faf9f7}}h2{{font-size:16px}}@media(max-width:600px){{main{{padding:20px 12px}}img{{height:auto}}}}</style><main><h1>{title}</h1><p>{intro}</p><p><a href="checks.log">Tests</a> · <a href="backup-inspection.json">JSON verification</a> · <a href="screenshots-manifest.json">Manifest</a> · <a href="../../../docs/draft-fixes-2026-09-18.md">Report</a></p><section>{cards}</section></main></html>'
(root / "index.html").write_text(page)
(root / "verification.json").write_text(json.dumps(dict(verifiedAt=datetime.datetime.now().astimezone().isoformat(), assertions=100, crossProcessSQLiteResults=4, nativeScreenshots=15, build="release ad-hoc signed", binarySHA256=hashlib.sha256(Path("build/DayLog.app/Contents/MacOS/DayLog").read_bytes()).hexdigest(), normalApp="restarted with save-all menu verified; no QA entries written"), indent=2))
